{
  "project_id": "e40e3f00b6574d0a8126",
  "name": "secure_todos_with_owner_rls",
  "query": "create table if not exists public.todos (
  id uuid,
  user_id uuid default auth.uid(),
  body text,
  done boolean,
  created_at timestamptz
);

alter table public.todos enable row level security;

grant select, insert, update, delete on table public.todos to authenticated;

drop policy if exists "Authenticated users can select their own todos" on public.todos;
drop policy if exists "Authenticated users can insert their own todos" on public.todos;
drop policy if exists "Authenticated users can update their own todos" on public.todos;
drop policy if exists "Authenticated users can delete their own todos" on public.todos;

create policy "Authenticated users can select their own todos"
on public.todos
for select
to authenticated
using ((select auth.uid()) = user_id);

create policy "Authenticated users can insert their own todos"
on public.todos
for insert
to authenticated
with check ((select auth.uid()) = user_id);

create policy "Authenticated users can update their own todos"
on public.todos
for update
to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

create policy "Authenticated users can delete their own todos"
on public.todos
for delete
to authenticated
using ((select auth.uid()) = user_id);"
}

